#!/usr/bin/env node
// Key ceremony for the xSOM rules authority (docs/secret-guard/RELEASE-RUNBOOK.md).
//
// Generates one Ed25519 key pair on this machine. The private seed is written
// to a new 0600 file OUTSIDE the repository and never printed; the public key
// and its keyId are printed with where each value goes. Run it yourself, on a
// trusted machine; no key is generated by CI or committed.
//
//   node secret-guard/scripts/generate-rules-authority-key.mjs [--out <file>]

import { generateKeyPairSync } from "node:crypto";
import {
  mkdirSync,
  openSync,
  writeSync,
  closeSync,
  realpathSync,
} from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

import { authorityKeyId } from "./rules-authority.mjs";

const repository = realpathSync(
  fileURLToPath(new URL("../../", import.meta.url)),
);

function fail(message) {
  process.stderr.write(`${message}\n`);
  process.exit(1);
}

function outputPath(argv, keyId) {
  const index = argv.indexOf("--out");
  if (index >= 0) {
    const value = argv[index + 1];
    if (value === undefined || value.startsWith("--"))
      fail("--out needs a file path.");
    return resolve(value);
  }
  const day = new Date().toISOString().slice(0, 10);
  return join(
    homedir(),
    ".xsom",
    "rules-authority",
    `rules-authority-${day}-${keyId.slice(0, 12)}.seed`,
  );
}

function insideRepository(path) {
  let directory = dirname(path);
  // Resolve the deepest existing parent: the file itself does not exist yet.
  for (;;) {
    try {
      directory = realpathSync(directory);
      break;
    } catch {
      const parent = dirname(directory);
      if (parent === directory) return false;
      directory = parent;
    }
  }
  return (
    directory === repository || directory.startsWith(`${repository}${sep}`)
  );
}

const { privateKey, publicKey } = generateKeyPairSync("ed25519");
const seed = privateKey
  .export({ format: "der", type: "pkcs8" })
  .subarray(-32)
  .toString("base64");
const jwk = publicKey.export({ format: "jwk" });
const publicKeyBase64 = Buffer.from(jwk.x, "base64url").toString("base64");
const keyId = authorityKeyId(publicKeyBase64);
const path = outputPath(process.argv.slice(2), keyId);

if (insideRepository(path))
  fail(
    `Refused: ${path} is inside the repository. The private seed must never be stored in git.`,
  );
mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
let descriptor;
try {
  // "wx": never overwrite an existing seed.
  descriptor = openSync(path, "wx", 0o600);
} catch (error) {
  fail(`Refused: cannot create ${path} (${error.code ?? "error"}).`);
}
writeSync(descriptor, `${seed}\n`);
closeSync(descriptor);

process.stdout.write(
  [
    "xSOM rules authority key generated.",
    "",
    `Private seed (secret, 0600): ${path}`,
    "  → AI Guard platform secret XSOM_RULES_SIGNING_KEY = the content of this file.",
    "    Keep an offline copy; never commit it, never paste it in a ticket or a log.",
    "",
    `Public key: ${publicKeyBase64}`,
    `keyId:      ${keyId}`,
    "  → GitHub repository variable XSOM_RULES_AUTHORITY_KEYS = the public key.",
    '    During a rotation: "<new key>,<old key>" until every workstation runs the new build.',
    "",
    "Then publish a release: packs signed with this key are accepted only by builds that contain it.",
    "",
  ].join("\n"),
);
